def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Final round defection is strictly dominant with deterministic execution.
    if n >= 99:
        return 'D'

    total_opp_def = 0
    my_def = 0
    unprov = 0

    for i in range(n):
        m, o = history[i]
        if m == 'D':
            my_def += 1
        if o == 'D':
            total_opp_def += 1
            # Count defections that followed a cooperative action from us.
            if i == 0 or history[i - 1][0] == 'C':
                unprov += 1

    # If the opponent has never defected, preserve cooperation until the end.
    if total_opp_def == 0:
        return 'C'

    window = 15 if n >= 15 else n
    start = n - window
    recent_opp_def = 0
    recent_unprov = 0

    for i in range(start, n):
        _, o = history[i]
        if o == 'D':
            recent_opp_def += 1
            if i == 0 or history[i - 1][0] == 'C':
                recent_unprov += 1

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    current_unprov = opp_last == 'D' and (n == 1 or history[-2][0] == 'C')

    if opp_last == 'D':
        if my_last == 'D':
            # Mutual defection: stay hard only against persistent defectors,
            # otherwise move back toward cooperation to repair coordination.
            if (opp_streak >= 4 or recent_opp_def >= 6 or unprov >= 3 or
                    total_opp_def * 100 >= n * 40):
                return 'D'
            return 'C'

        # We cooperated while the opponent defected.
        if opp_streak >= 2 or recent_opp_def >= 4:
            return 'D'

        if current_unprov:
            # First isolated unprovoked defection is forgiven; repeated
            # unprovoked exploitation is punished.
            if unprov <= 1:
                return 'C'
            if (unprov <= 2 and recent_unprov <= 1 and
                    my_def * 100 <= n * 12 and
                    total_opp_def * 100 <= n * 12):
                return 'C'
            return 'D'
        else:
            # Likely a lagged response to our earlier defection. If the
            # opponent is otherwise cooperative, forgive; if they are hard
            # or defecting often, continue punishing briefly.
            if (recent_opp_def >= 3 or unprov >= 3 or
                    total_opp_def * 100 >= n * 35):
                return 'D'
            if my_def > total_opp_def + 1:
                return 'C'
            return 'C'

    # Opponent cooperated last round.
    if my_last == 'D':
        # They tolerated our defection. Usually return to cooperation,
        # but keep punishing if recent behavior shows a defective pattern.
        if unprov >= 4 and recent_unprov >= 2:
            return 'D'
        if recent_opp_def >= 4:
            return 'D'
        return 'C'

    # Both cooperated last round.
    if unprov >= 4 and recent_unprov >= 2:
        return 'D'
    if recent_opp_def >= 5:
        return 'D'
    if total_opp_def * 100 >= n * 55:
        return 'D'
    if n >= 90 and recent_opp_def >= 3 and total_opp_def * 100 >= n * 35:
        return 'D'

    return 'C'
